<?php
$statement = db()->prepare('SELECT n.* FROM notifications n LEFT JOIN user_preferences p ON p.user_id=n.user_id WHERE n.user_id = :id AND COALESCE(p.in_app_notifications,1)=1 ORDER BY n.created_at DESC, n.id DESC');
$statement->execute(['id' => $user['id']]);
$notifications = $statement->fetchAll();
?>
<div class="section-title"><h2>Your notifications</h2><form action="action.php" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="read_all"><button class="button secondary" type="submit">Mark All as Read</button></form></div>
<?php foreach ($notifications as $item): ?><?php if (!empty($item['announcement_id'])): ?><?php $attachmentStatement=db()->prepare('SELECT attachment_name FROM announcements WHERE id=? AND attachment_path IS NOT NULL'); $attachmentStatement->execute([$item['announcement_id']]); $attachmentName=$attachmentStatement->fetchColumn(); ?><?php if($attachmentName): ?><p class="panel"><?= e($item['title']) ?> — <a href="attachment.php?announcement=<?= (int)$item['announcement_id'] ?>">Download <?= e($attachmentName) ?></a></p><?php endif; ?><?php endif; ?><?php endforeach; ?>
<section class="notification-list"><?php foreach ($notifications as $notification): ?><article class="notification <?= $notification['read_at'] ? 'read' : 'unread' ?>"><span class="notification-dot" aria-hidden="true"></span><div><form action="action.php" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="open_notification"><input type="hidden" name="notification_id" value="<?= (int) $notification['id'] ?>"><button class="notification-title" type="submit"><?= e($notification['title']) ?></button></form><span class="muted"><?= e(date_label($notification['created_at'])) ?></span></div><span class="notification-state"><?= $notification['read_at'] ? 'Read' : 'Unread' ?></span></article><?php endforeach; ?><?php if (!$notifications): ?><p class="empty">No notifications.</p><?php endif; ?></section>
